--
-- Table structure for table `face_template`
--

DROP TABLE IF EXISTS `face_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `face_template` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `employee_id` bigint NOT NULL,
  `model_name` varchar(50) NOT NULL,
  `embedding_dim` smallint NOT NULL DEFAULT '512',
  `embedding` blob NOT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT '1',
  `face_image_url` varchar(1024) DEFAULT NULL,
  `face_center_url` varchar(1024) DEFAULT NULL,
  `quality_score` float DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `pose` varchar(32) DEFAULT NULL,
  `emb_hash` binary(32) DEFAULT NULL,
  `dim` smallint DEFAULT NULL,
  `dtype` enum('f32') DEFAULT NULL,
  `endianness` enum('LE') DEFAULT NULL,
  `model_version` varchar(32) DEFAULT NULL,
  `norm` enum('raw','l2') DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_face_template_employee` (`employee_id`),
  KEY `idx_face_template_primary` (`is_primary`),
  KEY `idx_face_template_quality` (`quality_score`),
  CONSTRAINT `fk_face_template_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `face_template`
--

LOCK TABLES `face_template` WRITE;
